red":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.operation_property_role","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.pdf_operation_contract","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.physical_contract","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.property_applicability","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.property_applicability","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.property_definition","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.property_definition","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.registry_row","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.registry_row","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.release","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.release","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.release_finalization","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.runtime_binding","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.scientific_decision_rule","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.scientific_decision_rule","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.sql_admission","type":58,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.guard_finalized_insert()","name":"finalized_release","relation":"sem.vocabulary_member","type":7,"when":null},{"args":"","columns":[],"deferrable":false,"deferred":false,"function":"sem.refuse_immutable_mutation()","name":"semantic_immutable","relation":"sem.vocabulary_member","type":58,"when":null}],"views":[{"query":" WITH coverage_ AS MATERIALIZED (\n         SELECT pdf_published_revision.task_id,\n            pdf_published_revision.product_key,\n            (ops.pdf_companion_body(pdf_record_companion.product_id, pdf_record_companion.revision_id, pdf_record_companion.family, pdf_record_companion.local_id, pdf_record_companion.body))[''value''::text] AS value\n           FROM kb.pdf_record_companion\n             JOIN ops.pdf_published_revision ON pdf_published_revision.build_id = pdf_record_companion.product_id\n          WHERE pdf_record_companion.family = ''native_metadata''::text AND (pdf_record_companion.body ->> ''kind''::text) = ''recognition_coverage''::text\n        )\n SELECT task_id,\n    product_key,\n    value ->> ''section_pointer''::text AS section_pointer,\n    value ->> ''membership''::text AS membership,\n    value ->> ''universe''::text AS universe,\n    value ->> ''outcome''::text AS outcome,\n    value ->> ''policy''::text AS policy\n   FROM coverage_;","relation":"ops.pdf_published_coverage"},{"query":" SELECT pdf_published_revision.task_id,\n    pdf_published_revision.product_key,\n    pdf_record_access.pointer,\n    pdf_record_access.ordinal,\n    pdf_record_access.label,\n    pdf_record_access.parent_pointer,\n    pdf_record_access.section_pointer,\n    pdf_record_access.content_layer,\n    pdf_record_access.text,\n    pdf_record_access.native_json\n   FROM kb.pdf_record_access\n     JOIN ops.pdf_published_revision ON pdf_record_access.product_id = pdf_published_revision.build_id;","relation":"ops.pdf_published_item"},{"query":" SELECT pdf_published_revision.task_id,\n    pdf_published_revision.product_key,\n    pdf_record_region.pointer,\n    pdf_record_region.region_index,\n    pdf_record_region.page_no,\n    pdf_record_region.page_width,\n    pdf_record_region.page_height,\n    pdf_record_region.\"left\",\n    pdf_record_region.top,\n    pdf_record_region.\"right\",\n    pdf_record_region.bottom,\n    pdf_record_region.origin\n   FROM kb.pdf_record_region\n     JOIN ops.pdf_published_revision ON pdf_record_region.product_id = pdf_published_revision.build_id;","relation":"ops.pdf_published_region"},{"query":" SELECT pdf_published_revision.task_id,\n    pdf_published_revision.product_key,\n    pdf_published_revision.logical_digest AS content_digest,\n    pdf_published_revision.release_id,\n    contract_input.content_digest AS contract_digest,\n    pdf_published_revision.schema_digest,\n    pdf_published_revision.recipe_digest,\n    NULL::bigint AS parent_task_id,\n    NULL::text AS parent_product_key,\n    NULL::text AS parent_digest,\n    NULL::jsonb AS native_json,\n    ( SELECT pdf_record_companion.body - ARRAY[''source_scope''::text, ''page_start''::text, ''page_end''::text] AS anon_1\n           FROM kb.pdf_record_companion\n          WHERE pdf_record_companion.product_id = pdf_published_revision.build_id AND pdf_record_companion.revision_id = pdf_published_revision.build_id AND pdf_record_companion.family = ''health''::text AND pdf_record_companion.body ? ''source_scope''::text\n          ORDER BY pdf_record_companion.ordinal, pdf_record_companion.local_id\n         LIMIT 1) AS health,\n    NULL::bytea AS payload\n   FROM ops.pdf_published_revision\n     JOIN ops.pdf_build_validation ON pdf_build_validation.build_id = pdf_published_revision.build_id\n     JOIN sem.input contract_input ON contract_input.release_id = pdf_published_revision.release_id AND contract_input.input_kind = ''dependency''::text AND contract_input.input_name = ''pdf-domain/schema/pdf_products''::text;","relation":"ops.pdf_selected_product"}]}' AS JSONB) AS anon_1$$;
ALTER FUNCTION data.execution_contract_descriptor () OWNER TO corpus_sem_publisher;
REVOKE ALL PRIVILEGES ON FUNCTION data.execution_contract_descriptor () FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.execution_contract_descriptor () TO corpus_sem_admitter;
CREATE OR REPLACE FUNCTION data.prove_execution_catalog() RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 expected jsonb;
 spec jsonb;
 owner_name text;
BEGIN
 PERFORM sem.require_admission_caller();
 expected := data.execution_contract_descriptor();
 SELECT pg_catalog.pg_get_userbyid(pg_catalog.pg_namespace.nspowner) AS pg_get_userbyid_1 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname = 'sem' INTO owner_name;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.physical_contract AS artifact 
WHERE artifact.physical_id = (expected ->> 'physical_id') AND artifact.source_digest = (expected ->> 'physical_checks_source_digest')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'physical CHECK contract is unavailable', ERRCODE = '23514';
 END IF;
 SELECT item_1.value 
FROM sem.physical_contract AS artifact JOIN LATERAL jsonb_array_elements(artifact.checks) AS item_1(value) ON true LEFT OUTER JOIN pg_catalog.pg_constraint AS c ON c.conrelid = to_regclass((item_1.value ->> 'relation')) AND c.conname = (item_1.value ->> 'name') AND c.contype = 'c' 
WHERE artifact.physical_id = (expected ->> 'physical_id') AND (c.oid IS NULL OR NOT c.convalidated OR pg_get_expr(c.conbin, c.conrelid) IS DISTINCT FROM (item_1.value ->> 'expression')) 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('physical CHECK expression differs: %s.%s', coalesce(spec ->> 'relation', '<NULL>'), coalesce(spec ->> 'name', '<NULL>')), ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_catalog.pg_constraint AS c JOIN pg_catalog.pg_class AS rel ON rel.oid = c.conrelid JOIN pg_catalog.pg_namespace AS ns ON ns.oid = rel.relnamespace 
WHERE c.contype = 'c' AND expected['physical_relations'] ? (ns.nspname || '.' || rel.relname) AND NOT (EXISTS (SELECT 1 
FROM sem.physical_contract AS artifact JOIN LATERAL jsonb_array_elements(artifact.checks) AS item_1(value) ON true 
WHERE artifact.physical_id = (expected ->> 'physical_id') AND (item_1.value ->> 'relation') = (ns.nspname || '.' || rel.relname) AND (item_1.value ->> 'name') = c.conname)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unexpected physical CHECK', ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['views']) AS item(value) 
WHERE to_regclass((item.value ->> 'relation')) IS NULL OR regexp_replace(regexp_replace(pg_get_viewdef(to_regclass((item.value ->> 'relation')), true), '\mAS\M', '', 'gi'), '[[:space:]();]', '', 'g') IS DISTINCT FROM regexp_replace(regexp_replace((item.value ->> 'query'), '\mAS\M', '', 'gi'), '[[:space:]();]', '', 'g') 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = 'native selected-fact view differs', ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['functions']) AS item(value) LEFT OUTER JOIN pg_catalog.pg_proc AS p ON p.oid = pg_catalog.to_regprocedure((item.value ->> 'signature')) LEFT OUTER JOIN pg_catalog.pg_language AS l ON l.oid = p.prolang 
WHERE p.oid IS NULL OR CASE WHEN ((item.value ? 'body_profile')) THEN (item.value ->> 'body_profile') IS DISTINCT FROM 'postgresql-18-sql-standard-v1' OR (item.value ->> 'body_kind') IS DISTINCT FROM 'sql_standard' OR (item.value ->> 'server_major') IS DISTINCT FROM '18' OR (CAST(pg_catalog.current_setting('server_version_num') AS INTEGER) / 10000) != 18 OR p.prosqlbody IS NULL OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.pg_get_functiondef(p.oid), 'UTF8')), 'hex') IS DISTINCT FROM (item.value ->> 'body_sha256') OR (SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('kind', pg_catalog.pg_depend.deptype, 'type', i.type, 'schema', i.schema, 'name', i.name, 'identity', i.identity) ORDER BY CAST(pg_catalog.pg_depend.deptype AS TEXT) COLLATE "C", i.type COLLATE "C", i.schema COLLATE "C", i.name COLLATE "C", i.identity COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM pg_catalog.pg_depend JOIN LATERAL pg_catalog.pg_identify_object(pg_catalog.pg_depend.refclassid, pg_catalog.pg_depend.refobjid, pg_catalog.pg_depend.refobjsubid) AS i ON true 
WHERE pg_catalog.pg_depend.classid = CAST('pg_proc' AS REGCLASS) AND pg_catalog.pg_depend.objid = p.oid) IS DISTINCT FROM item.value['dependencies'] ELSE p.prosqlbody IS NOT NULL OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p.prosrc, 'UTF8')), 'hex') IS DISTINCT FROM (item.value ->> 'body_sha256') END OR p.prosecdef IS DISTINCT FROM CAST((item.value ->> 'security') AS BOOLEAN) OR p.proisstrict IS DISTINCT FROM CAST((item.value ->> 'strict') AS BOOLEAN) OR p.proleakproof IS DISTINCT FROM CAST((item.value ->> 'leakproof') AS BOOLEAN) OR p.proretset IS DISTINCT FROM CAST((item.value ->> 'setof') AS BOOLEAN) OR CAST(p.provolatile AS TEXT) IS DISTINCT FROM (item.value ->> 'volatility') OR CAST(p.proparallel AS TEXT) IS DISTINCT FROM (item.value ->> 'parallel') OR l.lanname IS DISTINCT FROM (item.value ->> 'language') OR p.prorettype IS DISTINCT FROM pg_catalog.to_regtype((item.value ->> 'result')) OR CASE WHEN (item.value ? 'result_definition') THEN (SELECT coalesce(jsonb_agg(configuration.value ORDER BY configuration.value), CAST('[]' AS JSONB)) AS coalesce_2 
FROM unnest(p.proconfig) AS configuration(value)) ELSE coalesce(to_jsonb(p.proconfig), CAST('[]' AS JSONB)) END IS DISTINCT FROM item.value['config'] OR pg_catalog.pg_get_userbyid(p.proowner) IS DISTINCT FROM CASE WHEN ((item.value ->> 'owner') = '$migration_owner') THEN owner_name ELSE (item.value ->> 'owner') END OR pg_catalog.has_function_privilege('corpus_sem_writer', p.oid, 'EXECUTE') IS DISTINCT FROM ((item.value['execute_roles'] ? 'corpus_sem_writer')) OR pg_catalog.has_function_privilege('corpus_sem_reader', p.oid, 'EXECUTE') IS DISTINCT FROM ((item.value['execute_roles'] ? 'corpus_sem_reader')) OR pg_catalog.has_function_privilege('corpus_sem_admitter', p.oid, 'EXECUTE') IS DISTINCT FROM ((item.value['execute_roles'] ? 'corpus_sem_admitter')) OR pg_catalog.has_function_privilege('corpus_sem_evaluator', p.oid, 'EXECUTE') IS DISTINCT FROM ((item.value['execute_roles'] ? 'corpus_sem_evaluator')) OR (EXISTS (SELECT 1 
FROM pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) AS acl 
WHERE acl.grantee = 0 AND acl.privilege_type = 'EXECUTE')) OR (item.value ? 'result_definition') AND pg_get_function_result(p.oid) IS DISTINCT FROM (item.value ->> 'result_definition') OR (item.value ? 'argument_definition') AND pg_get_function_arguments(p.oid) IS DISTINCT FROM (item.value ->> 'argument_definition') OR (item.value ? 'argument_defaults') AND pg_get_expr(p.proargdefaults, 0) IS DISTINCT FROM (item.value ->> 'argument_defaults') OR (item.value ? 'support') AND CAST(CAST(p.prosupport AS regproc) AS TEXT) IS DISTINCT FROM (item.value ->> 'support') OR (item.value ? 'cost') AND p.procost IS DISTINCT FROM CAST((item.value ->> 'cost') AS REAL) OR (item.value ? 'rows') AND p.prorows IS DISTINCT FROM CAST((item.value ->> 'rows') AS REAL) OR (item.value ? 'catalog_acl') AND (SELECT coalesce(jsonb_agg(jsonb_build_array(observed_acl.anon_1, observed_acl.privilege_type, observed_acl.is_grantable) ORDER BY observed_acl.anon_1, observed_acl.privilege_type, observed_acl.is_grantable), CAST('[]' AS JSONB)) AS coalesce_3 
FROM (SELECT CASE WHEN (a.grantee = 0) THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END AS anon_1, a.privilege_type AS privilege_type, a.is_grantable AS is_grantable 
FROM pg_catalog.aclexplode(coalesce(CAST(p.proacl AS aclitem[]), pg_catalog.acldefault(CAST('f' AS "char"), CAST(p.proowner AS OID)))) AS a ORDER BY CASE WHEN (a.grantee = 0) THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END, a.privilege_type, a.is_grantable) AS observed_acl) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_array(bound_acl.grantee, bound_acl.privilege, bound_acl.grantable) ORDER BY bound_acl.grantee, bound_acl.privilege, bound_acl.grantable), CAST('[]' AS JSONB)) AS coalesce_4 
FROM (SELECT CASE WHEN ((CAST(entry.value AS JSONB) ->> 0) = '$migration_owner') THEN CAST(owner_name AS TEXT) ELSE (CAST(entry.value AS JSONB) ->> 0) END AS grantee, (CAST(entry.value AS JSONB) ->> 1) AS privilege, bool_or(CAST((CAST(entry.value AS JSONB) ->> 2) AS BOOLEAN)) AS grantable 
FROM jsonb_array_elements(item.value['catalog_acl']) AS entry(value) GROUP BY CASE WHEN ((CAST(entry.value AS JSONB) ->> 0) = '$migration_owner') THEN CAST(owner_name AS TEXT) ELSE (CAST(entry.value AS JSONB) ->> 0) END, (CAST(entry.value AS JSONB) ->> 1)) AS bound_acl) ORDER BY item.value ->> 'signature' 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('native execution kernel differs: %s', coalesce(spec ->> 'signature', '<NULL>')), ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['triggers']) AS item(value) LEFT OUTER JOIN pg_catalog.pg_trigger AS t ON t.tgrelid = to_regclass((item.value ->> 'relation')) AND t.tgname = (item.value ->> 'name') AND NOT t.tgisinternal 
WHERE t.oid IS NULL OR (t.tgenabled NOT IN ('O', 'A')) OR t.tgfoid IS DISTINCT FROM to_regprocedure((item.value ->> 'function')) OR t.tgtype != CAST((item.value ->> 'type') AS INTEGER) OR t.tgdeferrable IS DISTINCT FROM CAST((item.value ->> 'deferrable') AS BOOLEAN) OR t.tginitdeferred IS DISTINCT FROM CAST((item.value ->> 'deferred') AS BOOLEAN) OR (SELECT to_jsonb(coalesce(array_agg(CAST(a.attname AS TEXT) ORDER BY attrs.position), ARRAY[]::TEXT[])) AS to_jsonb_1 
FROM unnest(CAST(t.tgattr AS SMALLINT[])) WITH ORDINALITY AS attrs(num, position) JOIN pg_catalog.pg_attribute AS a ON a.attrelid = t.tgrelid AND a.attnum = attrs.num) IS DISTINCT FROM item.value['columns'] OR pg_get_expr(t.tgqual, t.tgrelid) IS DISTINCT FROM (item.value ->> 'when') OR encode(t.tgargs, 'hex') IS DISTINCT FROM (item.value ->> 'args') 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('native execution guard differs: %s.%s', coalesce(spec ->> 'relation', '<NULL>'), coalesce(spec ->> 'name', '<NULL>')), ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['tables']) AS item(value) LEFT OUTER JOIN pg_catalog.pg_class AS relation ON relation.oid = to_regclass((item.value ->> 'relation')) 
WHERE relation.oid IS NULL OR relation.relkind != 'r' OR relation.relpersistence != 'p' OR relation.relrowsecurity OR relation.relforcerowsecurity OR pg_get_userbyid(relation.relowner) IS DISTINCT FROM (item.value ->> 'owner') OR (SELECT jsonb_agg(jsonb_build_object('name', a.attname, 'type', format_type(a.atttypid, a.atttypmod), 'not_null', a.attnotnull, 'identity', CAST(a.attidentity AS TEXT), 'generated', CAST(a.attgenerated AS TEXT), 'default', pg_get_expr(default_value.adbin, default_value.adrelid)) ORDER BY a.attname COLLATE "C") AS jsonb_agg_1 
FROM pg_catalog.pg_attribute AS a LEFT OUTER JOIN pg_catalog.pg_attrdef AS default_value ON default_value.adrelid = a.attrelid AND default_value.adnum = a.attnum 
WHERE a.attrelid = relation.oid AND a.attnum > 0 AND NOT a.attisdropped) IS DISTINCT FROM item.value['columns'] OR (SELECT to_jsonb((SELECT coalesce(array_agg(CAST(vector_attribute.attname AS TEXT) ORDER BY vector_position.position), ARRAY[]::TEXT[]) AS coalesce_1 
FROM unnest(c.conkey) WITH ORDINALITY AS vector_position(num, position) JOIN pg_catalog.pg_attribute AS vector_attribute ON vector_attribute.attrelid = c.conrelid AND vector_attribute.attnum = vector_position.num)) AS to_jsonb_1 
FROM pg_catalog.pg_constraint AS c 
WHERE c.conrelid = relation.oid AND c.contype = 'p') IS DISTINCT FROM item.value['primary_key'] OR (SELECT coalesce(jsonb_agg(jsonb_build_object('name', c.conname, 'columns', (SELECT coalesce(array_agg(CAST(vector_attribute.attname AS TEXT) ORDER BY vector_position.position), ARRAY[]::TEXT[]) AS coalesce_1 
FROM unnest(c.conkey) WITH ORDINALITY AS vector_position(num, position) JOIN pg_catalog.pg_attribute AS vector_attribute ON vector_attribute.attrelid = c.conrelid AND vector_attribute.attnum = vector_position.num), 'target', remote_schema.nspname || '.' || remote.relname, 'remote_columns', (SELECT coalesce(array_agg(CAST(vector_attribute.attname AS TEXT) ORDER BY vector_position.position), ARRAY[]::TEXT[]) AS coalesce_3 
FROM unnest(c.confkey) WITH ORDINALITY AS vector_position(num, position) JOIN pg_catalog.pg_attribute AS vector_attribute ON vector_attribute.attrelid = c.confrelid AND vector_attribute.attnum = vector_position.num), 'on_update', CAST(c.confupdtype AS TEXT), 'on_delete', CAST(c.confdeltype AS TEXT), 'match', CAST(c.confmatchtype AS TEXT), 'deferrable', c.condeferrable, 'deferred', c.condeferred, 'validated', c.convalidated) ORDER BY c.conname), CAST('[]' AS JSONB)) AS coalesce_2 
FROM pg_catalog.pg_constraint AS c JOIN pg_catalog.pg_class AS remote ON remote.oid = c.confrelid JOIN pg_catalog.pg_namespace AS remote_schema ON remote_schema.oid = remote.relnamespace 
WHERE c.conrelid = relation.oid AND c.contype = 'f') IS DISTINCT FROM item.value['foreign_keys'] OR (EXISTS (SELECT 1 
FROM (VALUES ('corpus_sem_writer'), ('corpus_sem_reader'), ('corpus_sem_evaluator'), ('corpus_sem_admitter')) AS actors (name) 
WHERE has_table_privilege(actors.name, relation.oid, 'SELECT') IS DISTINCT FROM ((coalesce(item.value['read_roles'], CAST('["corpus_sem_writer","corpus_sem_reader","corpus_sem_admitter","corpus_sem_evaluator"]' AS JSONB)) ? actors.name)) OR has_any_column_privilege(actors.name, relation.oid, 'SELECT') IS DISTINCT FROM ((coalesce(item.value['read_roles'], CAST('["corpus_sem_writer","corpus_sem_reader","corpus_sem_admitter","corpus_sem_evaluator"]' AS JSONB)) ? actors.name)) OR has_table_privilege(actors.name, relation.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(actors.name, relation.oid, 'INSERT,UPDATE,REFERENCES'))) OR (EXISTS (SELECT 1 
FROM aclexplode(coalesce(relation.relacl, acldefault(CAST('r' AS "char"), relation.relowner))) AS acl(grantor, grantee, privilege_type, is_grantable) 
WHERE acl.grantee = 0)) 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('native source frame projection differs: %s', coalesce(spec ->> 'relation', '<NULL>')), ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['readers']) AS item(value) JOIN LATERAL jsonb_array_elements_text(item.value['roles']) AS required_role_1(name) ON true 
WHERE to_regclass((item.value ->> 'relation')) IS NULL OR NOT has_table_privilege(required_role_1.name, to_regclass((item.value ->> 'relation')), 'SELECT') 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('required native read capability is unavailable: %s', coalesce(spec ->> 'relation', '<NULL>')), ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['indexes']) AS item(value) LEFT OUTER JOIN pg_catalog.pg_index AS i ON i.indexrelid = to_regclass((item.value ->> 'index')) 
WHERE i.indexrelid IS NULL OR NOT i.indisvalid OR NOT i.indisready OR i.indrelid IS DISTINCT FROM to_regclass((item.value ->> 'relation')) OR pg_get_indexdef(i.indexrelid) IS DISTINCT FROM (item.value ->> 'definition') 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = 'native source search index differs', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(expected['privileges']) AS policy(value) JOIN (VALUES ('corpus_sem_writer'), ('corpus_sem_reader'), ('corpus_sem_evaluator'), ('corpus_sem_fitter'), ('corpus_sem_admitter')) AS principal (name) ON true 
WHERE (policy.value ->> 'kind') = 'schema' AND pg_catalog.has_schema_privilege(principal.name, policy.value ->> 'name', 'CREATE'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'purpose principal has effective schema CREATE', ERRCODE = '42501';
 END IF;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(expected['privileges']) AS policy(value) 
WHERE CASE WHEN ((policy.value ->> 'kind') = 'table') THEN (SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(edges.grantee, edges.privilege, edges.grantable) ORDER BY edges.grantee COLLATE "C", edges.privilege COLLATE "C", edges.grantable), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT pg_catalog.pg_get_userbyid(acl.grantor) AS grantor, CASE WHEN (acl.grantee = 0) THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END AS grantee, acl.privilege_type AS privilege, acl.is_grantable AS grantable, NULL AS "column", pg_catalog.pg_get_userbyid(pg_catalog.pg_class.relowner) AS owner 
FROM pg_catalog.pg_class JOIN LATERAL pg_catalog.aclexplode(coalesce(pg_catalog.pg_class.relacl, pg_catalog.acldefault(CAST('r' AS "char"), pg_catalog.pg_class.relowner))) AS acl ON true 
WHERE pg_catalog.pg_class.oid = pg_catalog.to_regclass((policy.value ->> 'name')) AND acl.grantee != pg_catalog.pg_class.relowner) AS edges) IS DISTINCT FROM policy.value['acl'] OR (EXISTS (SELECT pg_catalog.pg_get_userbyid(acl.grantor) AS grantor, CASE WHEN (acl.grantee = 0) THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END AS grantee, acl.privilege_type AS privilege, acl.is_grantable AS grantable, pg_catalog.pg_attribute.attname AS "column", pg_catalog.pg_get_userbyid(pg_catalog.pg_class.relowner) AS owner 
FROM pg_catalog.pg_class JOIN pg_catalog.pg_attribute ON pg_catalog.pg_attribute.attrelid = pg_catalog.pg_class.oid JOIN LATERAL pg_catalog.aclexplode(pg_catalog.pg_attribute.attacl) AS acl ON true 
WHERE pg_catalog.pg_class.oid = pg_catalog.to_regclass((policy.value ->> 'name')) AND pg_catalog.pg_attribute.attnum > 0 AND NOT pg_catalog.pg_attribute.attisdropped)) ELSE (SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(edges.grantee, edges.privilege, edges.grantable) ORDER BY edges.grantee COLLATE "C", edges.privilege COLLATE "C", edges.grantable), CAST('[]' AS JSONB)) AS coalesce_2 
FROM (SELECT pg_catalog.pg_get_userbyid(acl.grantor) AS grantor, CASE WHEN (acl.grantee = 0) THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END AS grantee, acl.privilege_type AS privilege, acl.is_grantable AS grantable, NULL AS "column", pg_catalog.pg_get_userbyid(pg_catalog.pg_namespace.nspowner) AS owner 
FROM pg_catalog.pg_namespace JOIN LATERAL pg_catalog.aclexplode(coalesce(pg_catalog.pg_namespace.nspacl, pg_catalog.acldefault(CAST('n' AS "char"), pg_catalog.pg_namespace.nspowner))) AS acl ON true 
WHERE pg_catalog.pg_namespace.nspname = (policy.value ->> 'name') AND acl.grantee != pg_catalog.pg_namespace.nspowner) AS edges) IS DISTINCT FROM (SELECT coalesce(pg_catalog.jsonb_agg(entry.value ORDER BY (entry.value ->> 0) COLLATE "C", (entry.value ->> 1) COLLATE "C", CAST((entry.value ->> 2) AS BOOLEAN)), CAST('[]' AS JSONB)) AS coalesce_3 
FROM jsonb_array_elements(policy.value['acl']) AS entry(value) 
WHERE (entry.value ->> 0) IS DISTINCT FROM (SELECT pg_catalog.pg_get_userbyid(pg_catalog.pg_namespace.nspowner) AS pg_get_userbyid_1 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname = (policy.value ->> 'name'))) END)) THEN
  RAISE EXCEPTION USING MESSAGE = 'declared table/schema privilege policy differs', ERRCODE = '42501';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_catalog.pg_roles AS r 
WHERE r.rolname = 'corpus_sem_evaluator' AND (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls))) OR (EXISTS (SELECT 1 
FROM pg_catalog.pg_auth_members AS m JOIN pg_catalog.pg_roles AS r ON r.oid = m.member 
WHERE r.rolname = 'corpus_sem_evaluator'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unrestricted evaluation principal', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM (VALUES ('sem'), ('data'), ('ops'), ('kb'), ('eval')) AS schemas (name) 
WHERE coalesce(pg_catalog.has_schema_privilege('corpus_sem_evaluator', pg_catalog.to_regnamespace(schemas.name), 'CREATE'), false))) THEN
  RAISE EXCEPTION USING MESSAGE = 'evaluator schema mutation privilege', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace 
WHERE n.nspname IN ('sem', 'data', 'ops', 'kb', 'eval') AND c.relkind IN ('r', 'p') AND (pg_catalog.has_table_privilege('corpus_sem_evaluator', c.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR pg_catalog.has_any_column_privilege('corpus_sem_evaluator', c.oid, 'INSERT,UPDATE')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'evaluator direct write privilege', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM (VALUES ('corpus_sem_writer'), ('corpus_sem_reader')) AS roles (name) 
WHERE coalesce(pg_catalog.has_schema_privilege(roles.name, pg_catalog.to_regnamespace('eval'), 'USAGE,CREATE'), false))) OR (EXISTS (SELECT 1 
FROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace, (VALUES ('corpus_sem_writer'), ('corpus_sem_reader')) AS roles (name) 
WHERE n.nspname = 'eval' AND c.relkind IN ('r', 'p') AND (pg_catalog.has_table_privilege(roles.name, c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR pg_catalog.has_any_column_privilege(roles.name, c.oid, 'SELECT,INSERT,UPDATE'))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'reference data leaked to source principal', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_catalog.pg_roles AS r 
WHERE r.rolname IN ('corpus_sem_writer', 'corpus_sem_reader') AND (r.rolsuper OR r.rolcreaterole OR r.rolbypassrls))) OR pg_catalog.pg_has_role('corpus_sem_writer', 'corpus_sem_publisher', 'MEMBER') OR pg_catalog.pg_has_role('corpus_sem_reader', 'corpus_sem_publisher', 'MEMBER') OR pg_catalog.pg_has_role('corpus_sem_writer', owner_name, 'MEMBER') OR pg_catalog.pg_has_role('corpus_sem_reader', owner_name, 'MEMBER')) THEN
  RAISE EXCEPTION USING MESSAGE = 'unrestricted application principal', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM (VALUES ('corpus_sem_writer'), ('corpus_sem_reader')) AS roles (name), (VALUES ('sem'), ('data'), ('ops'), ('kb')) AS schemas (name) 
WHERE coalesce(pg_catalog.has_schema_privilege(roles.name, pg_catalog.to_regnamespace(schemas.name), 'CREATE'), false))) THEN
  RAISE EXCEPTION USING MESSAGE = 'application schema mutation privilege', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace, (VALUES ('corpus_sem_writer'), ('corpus_sem_reader')) AS roles (name) 
WHERE n.nspname IN ('sem', 'data') AND c.relkind IN ('r', 'p') AND (pg_catalog.has_table_privilege(roles.name, c.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR pg_catalog.has_any_column_privilege(roles.name, c.oid, 'INSERT,UPDATE')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'application direct semantic write privilege', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM (VALUES ('corpus_sem_writer'), ('corpus_sem_reader')) AS roles (name), (VALUES ('data.publish_contract_batch(text,text,text,bytea)'), ('data.validate_state(text,text)'), ('data.publish_pre_execution_analysis_batch(text,text,text,bytea,bigint)'), ('data.finish_pre_contract_evaluation(bigint,text,text)')) AS kernels (signature) 
WHERE coalesce(pg_catalog.has_function_privilege(roles.name, pg_catalog.to_regprocedure(kernels.signature), 'EXECUTE'), false))) THEN
  RAISE EXCEPTION USING MESSAGE = 'application private kernel privilege', ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(expected['checks']) AS item(value) LEFT OUTER JOIN pg_catalog.pg_constraint AS c ON c.conrelid = to_regclass((item.value ->> 'relation')) AND c.conname = (item.value ->> 'name') 
WHERE c.oid IS NULL OR NOT c.convalidated OR pg_get_constraintdef(c.oid) IS DISTINCT FROM (item.value ->> 'definition') 
 LIMIT 1 INTO spec;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = format('native CHECK expression differs: %s', coalesce(spec ->> 'relation', '<NULL>')), ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace 
WHERE n.nspname = 'eval' AND c.relkind IN ('r', 'p') AND pg_catalog.has_table_privilege('corpus_sem_admitter', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'admission principal has reference access', ERRCODE = '42501';
 END IF;
 IF (EXISTS (SELECT 1 
FROM (VALUES ('corpus_sem_writer'), ('corpus_sem_reader'), ('corpus_sem_admitter'), ('corpus_sem_evaluator')) AS principal (name) 
WHERE pg_catalog.has_database_privilege(principal.name, pg_catalog.current_database(), 'TEMP') OR pg_catalog.pg_has_role(principal.name, 'corpus_sem_publisher', 'MEMBER') OR pg_catalog.pg_has_role(principal.name, owner_name, 'MEMBER'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'privileged runtime principal', ERRCODE = '42501';
 END IF;
END$$;
ALTER FUNCTION data.prove_execution_catalog () OWNER TO corpus_sem_publisher;
REVOKE ALL PRIVILEGES ON FUNCTION data.prove_execution_catalog () FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.prove_execution_catalog () TO corpus_sem_admitter;
CREATE OR REPLACE FUNCTION data.prove_execution_release(r text) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 expected jsonb;
BEGIN
 PERFORM data.prove_execution_catalog();
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release_finalization 
WHERE sem.release_finalization.release_id = r))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release is not finalized', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release 
WHERE sem.release.release_id = r))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown execution release', ERRCODE = '23514';
 END IF;
 IF (((EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = r)) OR (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name IN ('data_operations.json', 'data_operation_native_definitions.json')))) AND NOT (EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = r AND sem.data_operation_release.native_kernel_digest = (CAST(sem.data_operation_native_descriptor() AS JSONB) ->> 'source_digest')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release was prepared for a different native kernel; re-prepare it', ERRCODE = '23514';
 END IF;
 expected := data.execution_contract_descriptor();
 PERFORM sem.require_archive_bytes(r);
 PERFORM sem.require_execution_projection(r);
 PERFORM sem.require_execution_binding_facts(r);
 IF (EXISTS (SELECT 1 
FROM sem.release JOIN jsonb_array_elements((CAST(convert_from(sem.release.prepared_bytes, 'UTF8') AS JSONB))['products']['diagnostics']) AS diagnostic(value) ON true 
WHERE sem.release.release_id = r AND ((diagnostic.value ->> 'outcome') IN ('unsupported', 'unresolved') OR (diagnostic.value ->> 'outcome') = 'unchecked' AND NOT ((diagnostic.value ->> 'code') = 'unchecked_term' AND (diagnostic.value ->> 'message') = 'not4curation:unchecked')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release contains unresolved or unchecked required semantics', ERRCODE = '23514';
 END IF;
 IF (EXISTS (WITH RECURSIVE archived_native_constraint_projection AS 
(SELECT CAST(convert_from(native.content, 'UTF8') AS JSONB) AS projection, CAST(convert_from(model.content, 'UTF8') AS JSONB) AS model 
FROM sem.artifact AS native JOIN sem.artifact AS model ON model.release_id = native.release_id AND model.artifact_name = 'data_operations.json' 
WHERE native.release_id = r AND native.artifact_name = 'data_operation_native_definitions.json' AND (CAST(convert_from(native.content, 'UTF8') AS JSONB) ->> 'model_digest') = encode(sha256(model.content), 'hex')), 
native_constraint_json_roots AS 
(SELECT sem.class_definition.class_id AS class_id 
FROM archived_native_constraint_projection JOIN jsonb_array_elements(archived_native_constraint_projection.projection['kinds']) AS projected_kind(value) ON true JOIN sem.class_definition ON sem.class_definition.release_id = r AND sem.class_definition.class_id = (projected_kind.value ->> 'kind') 
WHERE EXISTS (SELECT 1 
FROM jsonb_array_elements(archived_native_constraint_projection.model['kinds']) AS declared_kind(value) 
WHERE (declared_kind.value ->> 'semantic_id') = sem.class_definition.class_id AND (declared_kind.value ->> 'category') = 'class')), 
native_constraint_json_edges AS 
(SELECT sem.property_applicability.class_id AS source, sem.class_definition.class_id AS target 
FROM sem.property_applicability JOIN sem.class_definition ON sem.class_definition.release_id = sem.property_applicability.release_id AND sem.class_definition.name = sem.property_applicability.range_name 
WHERE sem.property_applicability.release_id = r AND coalesce(CAST((sem.property_applicability.constraints ->> 'inlined') AS BOOLEAN), false) UNION SELECT sem.class_hierarchy.class_id AS class_id, sem.class_hierarchy.ancestor_id AS ancestor_id 
FROM sem.class_hierarchy 
WHERE sem.class_hierarchy.release_id = r), 
native_constraint_json_classes(class_id) AS 
(SELECT native_constraint_json_roots.class_id AS class_id 
FROM native_constraint_json_roots UNION SELECT native_constraint_json_edges.target AS target 
FROM native_constraint_json_classes JOIN native_constraint_json_edges ON native_constraint_json_edges.source = native_constraint_json_classes.class_id)
 SELECT 1 
FROM sem.property_applicability 
WHERE sem.property_applicability.release_id = r AND ((sem.property_applicability.constraint_scope NOT IN ('shape', 'accepted_value')) OR ((sem.property_applicability.constraints ->> 'pattern') IS NOT NULL OR (coalesce(sem.property_applicability.constraints['patterns'], CAST('[]' AS JSONB)) NOT IN (CAST('[]' AS JSONB), CAST('null' AS JSONB)))) AND NOT (sem.property_applicability.constraint_scope = 'shape' AND sem.property_applicability.class_id IN (SELECT native_constraint_json_classes.class_id 
FROM native_constraint_json_classes))))) THEN
  IF (NOT (EXISTS (WITH archived_native_constraint_projection AS 
(SELECT CAST(convert_from(native.content, 'UTF8') AS JSONB) AS projection, CAST(convert_from(model.content, 'UTF8') AS JSONB) AS model 
FROM sem.artifact AS native JOIN sem.artifact AS model ON model.release_id = native.release_id AND model.artifact_name = 'data_operations.json' 
WHERE native.release_id = r AND native.artifact_name = 'data_operation_native_definitions.json' AND (CAST(convert_from(native.content, 'UTF8') AS JSONB) ->> 'model_digest') = encode(sha256(model.content), 'hex'))
 SELECT 1 
FROM archived_native_constraint_projection)) AND (EXISTS (WITH archived_native_constraint_projection AS 
(SELECT CAST(convert_from(native.content, 'UTF8') AS JSONB) AS projection, CAST(convert_from(model.content, 'UTF8') AS JSONB) AS model 
FROM sem.artifact AS native JOIN sem.artifact AS model ON model.release_id = native.release_id AND model.artifact_name = 'data_operations.json' 
WHERE native.release_id = r AND native.artifact_name = 'data_operation_native_definitions.json' AND (CAST(convert_from(native.content, 'UTF8') AS JSONB) ->> 'model_digest') = encode(sha256(model.content), 'hex'))
 SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'data_operations.json'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'archived DDO native constraint projection is missing or incompatible with the model', ERRCODE = '23514';
  END IF;
  RAISE EXCEPTION USING MESSAGE = 'unsupported required native constraint scope or pattern', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release 
WHERE sem.release.release_id = r AND sem.release.profile = 'semantic-2'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'execution requires a current composed release', ERRCODE = '23514';
 END IF;
 IF (EXISTS (WITH admitted_inference_rules AS 
(SELECT CAST(convert_from(sem.registry_row.body, 'UTF8') AS JSONB) AS rule 
FROM sem.registry_row 
WHERE sem.registry_row.release_id = r AND sem.registry_row.kind = 'inference_rule'), 
admitted_inference_signatures AS 
(SELECT admitted_inference_rules.rule ->> 'kind' AS kind, admitted_inference_rules.rule ->> 'predicate' AS predicate, coalesce(nullif(admitted_inference_rules.rule ->> 'target', ''), admitted_inference_rules.rule ->> 'predicate') AS target 
FROM admitted_inference_rules)
 SELECT 1 
FROM (SELECT 1 AS invalid 
FROM admitted_inference_signatures 
WHERE admitted_inference_signatures.kind IS NULL OR admitted_inference_signatures.predicate IS NULL OR admitted_inference_signatures.target IS NULL OR (admitted_inference_signatures.kind NOT IN ('inverse', 'symmetric', 'transitive', 'subproperty')) OR NOT (EXISTS (SELECT 1 
FROM sem.property_applicability 
WHERE sem.property_applicability.release_id = r AND sem.property_applicability.property_id = admitted_inference_signatures.predicate)) OR NOT (EXISTS (SELECT 1 
FROM sem.property_applicability 
WHERE sem.property_applicability.release_id = r AND sem.property_applicability.property_id = admitted_inference_signatures.target)) UNION ALL SELECT 1 AS anon_1 
FROM admitted_inference_signatures JOIN sem.property_applicability ON sem.property_applicability.release_id = r AND sem.property_applicability.property_id = admitted_inference_signatures.predicate LEFT OUTER JOIN sem.class_definition AS source_range ON source_range.release_id = r AND source_range.name = sem.property_applicability.range_name LEFT OUTER JOIN sem.property_applicability AS target ON target.release_id = r AND target.property_id = admitted_inference_signatures.target AND target.class_id = CASE WHEN (admitted_inference_signatures.kind = 'subproperty') THEN sem.property_applicability.class_id ELSE source_range.class_id END LEFT OUTER JOIN sem.class_definition AS target_range ON target_range.release_id = r AND target_range.name = target.range_name 
WHERE coalesce(CAST((sem.property_applicability.constraints ->> 'inlined') AS BOOLEAN), false) OR source_range.class_id IS NULL OR target.property_id IS NULL OR coalesce(CAST((target.constraints ->> 'inlined') AS BOOLEAN), false) OR target_range.class_id IS NULL OR NOT (target_range.class_id = CASE WHEN (admitted_inference_signatures.kind IN ('subproperty', 'transitive')) THEN source_range.class_id ELSE sem.property_applicability.class_id END OR (EXISTS (SELECT 1 
FROM sem.class_hierarchy 
WHERE sem.class_hierarchy.release_id = r AND sem.class_hierarchy.ancestor_id = target_range.class_id AND sem.class_hierarchy.class_id = CASE WHEN (admitted_inference_signatures.kind IN ('subproperty', 'transitive')) THEN source_range.class_id ELSE sem.property_applicability.class_id END))) UNION ALL SELECT 1 AS anon_2 
FROM sem.property_applicability JOIN (VALUES ('symmetric'), ('transitive')) AS inference_flag (name) ON true 
WHERE sem.property_applicability.release_id = r AND coalesce(CAST(sem.property_applicability.constraints ->> inference_flag.name AS BOOLEAN), false) AND NOT (EXISTS (SELECT 1 
FROM admitted_inference_signatures 
WHERE admitted_inference_signatures.kind = inference_flag.name AND sem.property_applicability.property_id = admitted_inference_signatures.predicate AND sem.property_applicability.property_id = admitted_inference_signatures.target)) UNION ALL SELECT 1 AS anon_3 
FROM sem.property_applicability LEFT OUTER JOIN LATERAL (SELECT count(DISTINCT inverse.property_id) AS count, min(inverse.property_id) AS target 
FROM sem.property_applicability AS inverse 
WHERE inverse.release_id = r AND (inverse.property_id = (sem.property_applicability.constraints ->> 'inverse') OR (inverse.constraints ->> 'name') = (sem.property_applicability.constraints ->> 'inverse'))) AS inverse_target ON true 
WHERE sem.property_applicability.release_id = r AND nullif((sem.property_applicability.constraints ->> 'inverse'), '') IS NOT NULL AND (inverse_target.count != 1 OR NOT (EXISTS (SELECT 1 
FROM admitted_inference_signatures 
WHERE admitted_inference_signatures.kind = 'inverse' AND sem.property_applicability.property_id = admitted_inference_signatures.predicate AND admitted_inference_signatures.target = inverse_target.target)))) AS invalid_native_inference)) THEN
  RAISE EXCEPTION USING MESSAGE = 'unsupported required native binary inference profile', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release 
WHERE sem.release.release_id = r AND CAST(convert_from(sem.release.manifest_bytes, 'UTF8') AS JSONB) ? 'data_operation_model'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'native execution requires the current declared data operation model', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM sem.registry_row 
WHERE sem.registry_row.release_id = r AND sem.registry_row.kind = 'execution_model')) THEN
  RAISE EXCEPTION USING MESSAGE = 'target archive contains legacy execution model', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'operation/scientific-policy.json')) THEN
  PERFORM sem.require_scientific_layout(r);
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.deployment_admission 
WHERE sem.deployment_admission.release_id = r AND sem.deployment_admission.physical_id = (expected ->> 'physical_id') AND sem.deployment_admission.deployment_id = encode(sha256(convert_to(CAST(expected AS TEXT), 'UTF8')), 'hex') AND sem.deployment_admission.kind = 'native' AND sem.deployment_admission.content = convert_to(CAST(expected AS TEXT), 'UTF8')))) THEN
  PERFORM sem.record_deployment_admission(r, expected ->> 'physical_id', encode(sha256(convert_to(CAST(expected AS TEXT), 'UTF8')), 'hex'), 'native', convert_to(CAST(expected AS TEXT), 'UTF8'));
 END IF;
END$$;
ALTER FUNCTION data.prove_execution_release (text) OWNER TO corpus_sem_publisher;
REVOKE ALL PRIVILEGES ON FUNCTION data.prove_execution_release (text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.prove_execution_release (text) TO corpus_sem_admitter;
CREATE OR REPLACE FUNCTION data.require_execution_release(r text) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 expected jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release_finalization 
WHERE sem.release_finalization.release_id = r))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release is not finalized', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.release 
WHERE sem.release.release_id = r))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown execution release', ERRCODE = '23514';
 END IF;
 IF (((EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = r)) OR (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name IN ('data_operations.json', 'data_operation_native_definitions.json')))) AND NOT (EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = r AND sem.data_operation_release.native_kernel_digest = (CAST(sem.data_operation_native_descriptor() AS JSONB) ->> 'source_digest')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release was prepared for a different native kernel; re-prepare it', ERRCODE = '23514';
 END IF;
 expected := data.execution_contract_descriptor();
 IF (EXISTS (SELECT 1 
FROM sem.deployment_admission 
WHERE sem.deployment_admission.release_id = r AND sem.deployment_admission.physical_id = (expected ->> 'physical_id') AND sem.deployment_admission.deployment_id = encode(sha256(convert_to(CAST(expected AS TEXT), 'UTF8')), 'hex') AND sem.deployment_admission.kind = 'native' AND sem.deployment_admission.content = convert_to(CAST(expected AS TEXT), 'UTF8'))) THEN
  RETURN;
 END IF;
 IF (NOT (pg_has_role(SESSION_USER, 'corpus_sem_admitter', 'USAGE') OR pg_has_role(SESSION_USER, (SELECT pg_catalog.pg_get_userbyid(pg_catalog.pg_namespace.nspowner) AS pg_get_userbyid_1 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname = 'sem'), 'MEMBER'))) THEN
  RAISE EXCEPTION USING MESSAGE = concat('release lacks a current deployment receipt. Run ci release check --native-proof --release ', r, ' on the acquired target'), ERRCODE = '23514';
 END IF;
 PERFORM data.prove_execution_release(r);
END$$;
ALTER FUNCTION data.require_execution_release (text) OWNER TO corpus_sem_publisher;
REVOKE ALL PRIVILEGES ON FUNCTION data.require_execution_release (text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION data.require_execution_release (text) TO corpus_sem_writer;
GRANT EXECUTE ON FUNCTION data.require_execution_release (text) TO corpus_sem_reader;
GRANT EXECUTE ON FUNCTION data.require_execution_release (text) TO corpus_sem_evaluator;
GRANT EXECUTE ON FUNCTION data.require_execution_release (text) TO corpus_sem_admitter;